update orders
status = #{status}, checkout_time = #{checkoutTime}, pay_method=#{payMethod}, pay_status = #{payStatus}, estimated_delivery_time = #{estimatedDeliveryTime}, delivery_status = #{deliveryStatus}, delivery_time = #{deliveryTime}, cancel_reason=#{cancelReason}, cancel_time=#{cancelTime}, rejection_reason=#{rejectionReason},
where id = #{id}

mapper.select:
select * from orders


        and number like concat('%',#{number},'%')


        and phone like concat('%',#{phone},'%')


        and user_id = #{userId}


        and status = #{status}


        and order_time >= #{beginTime}


        and order_time <= #{endTime}


order by order_time desc

select sum(amount) from orders


        and status = #{status}


        and order_time >= #{begin}


        and order_time <= #{end}

select count(*) from orders


        and status = #{status}


        and order_time >= #{begin}


        and order_time <= #{end}

select od.name name, sum(od.number) number from order_detail od join orders o on od.order_id = o.id where o.status = 5
and order_time >= #{startTime}
and order_time <= #{endTime}
group by od.name order by number desc limit 10
